const body = $json.body || $json;
const notes = String(body.notes || body.progressNotes || '').slice(0, 8000);
if (!notes.trim()) {
  return [{ json: {
    matches: [],
    model: 'none',
    failureEvent: { type: 'FailureEvent', source: 'PrefillHealer', reason: 'empty notes', httpStatus: 400 }
  } }];
}
const taxonomy = body.taxonomy || {};
const lines = Array.isArray(taxonomy.lines) ? taxonomy.lines : [];
const aliases = lines.flatMap((l) => (l.aliases || [l.label]).map((a) => `${a} => ${l.label} [${l.id}]`)).slice(0, 400);
const tasks = body.tasks || {};
const prompt = [
  'You are the WEOTT Nexus catalogue matcher. Deterministic regex already ran.',
  'Return ONLY JSON: {"matches":[{"field":"keyItems|menuType|lineLabel|vesselType|veto","value":"exact catalogue label, id, or quoted notes","confidence":0-1,"evidence_span":"verbatim substring of NOTES"}]}',
  'Never invent a label that is not in the catalogue list.',
  'Never output guestCount, margin, rates, or any £ amount that is not a verbatim quote from NOTES.',
  'KEY ITEMS (#2): if NOTES mix a call-log with event codes in one sentence, or paraphrase a menu without HFB/2CSD/3CSD, return field=keyItems with evidence_span copied from NOTES. Strip voicemail/spoke to/called. Do not rewrite.',
  'VETO (#4): TV/MIC/AWARDS/SCREEN — do not map to TV - 55" unless NOTES explicitly add a TV. Generic RECEPTION is not Cocktail Reception unless the words COCKTAIL RECEPTION appear. If regex would have over-committed, return field=veto with that label and confidence 0.2.',
  'confidence < 0.75 if the token is ambiguous. confidence >= 0.9 only for explicit catalogue wording.',
  tasks.keyItems ? 'This request needs a keyItems span.' : 'Skip keyItems unless obvious.',
  tasks.collisionVeto ? 'This request is a collision veto (TV/MIC/AWARDS/RECEPTION).' : 'Skip veto unless obvious.',
  'CATALOGUE:',
  aliases.join('\n'),
  'NOTES:',
  notes
].join('\n');
return [{ json: { notes, prompt, ok: true } }];

const parsed = $json;
const matches = Array.isArray(parsed.matches) ? parsed.matches : (parsed.output?.matches || []);
return [{ json: {
  matches: matches.map((m) => ({
    field: String(m.field || ''),
    value: String(m.value || ''),
    confidence: Math.max(0, Math.min(1, Number(m.confidence) || 0)),
    evidence_span: String(m.evidence_span || '')
  })),
  model: 'n8n Google Gemini Chat Model / models/gemini-2.0-flash (Free Tier)'
} }];
